if (!tenant) return c.json({ error: 'missing X-Tenant header' }, 400);
if (!deps.tenants.get(tenant)) return c.json({ error: `unknown tenant ${tenant}` }, 404);

const verdict = deps.limiter.check(tenant, deps.config.rateLimitMaxRequests, deps.config.rateLimitWindowMs);
if (!verdict.allowed) {
  return c.json({ error: 'rate limit exceeded' }, 429, { 'Retry-After': String(verdict.retryAfterSec) });
}

